uint32_t crc32c_Extend(uint32_t init_crc, const char* data, size_t n) {
  // Pre-condition the CRC
  uint32_t crc = init_crc ^ 0xffffffffU;

  // Process as many 32-byte chunks as possible using the stride tables
  const uint8_t* ptr = reinterpret_cast<const uint8_t*>(data);
  while (n >= 32) {
    crc ^= ReadUint32LE(ptr);
    ptr += 4;
    n -= 4;

    // Process 4 bytes at a time using the stride tables
    crc = kStrideExtensionTable0[(crc >> 0) & 0xff] ^
          kStrideExtensionTable1[(crc >> 8) & 0xff] ^
          kStrideExtensionTable2[(crc >> 16) & 0xff] ^
          kStrideExtensionTable3[(crc >> 24) & 0xff];
  }

  // Process remaining 4-byte chunks
  while (n >= 4) {
    crc ^= ReadUint32LE(ptr);
    ptr += 4;
    n -= 4;
    crc = kStrideExtensionTable0[(crc >> 0) & 0xff] ^
          kStrideExtensionTable1[(crc >> 8) & 0xff] ^
          kStrideExtensionTable2[(crc >> 16) & 0xff] ^
          kStrideExtensionTable3[(crc >> 24) & 0xff];
  }

  // Process remaining bytes
  while (n > 0) {
    crc = kByteExtensionTable[(crc ^ static_cast<uint8_t>(*ptr)) & 0xff];
    ptr++;
    n--;
  }

  // Post-condition the CRC
  return crc ^ 0xffffffffU;
}
